// Validate ensures the union discriminant is valid.
func (u InitiativeRequest) Validate() error {
	switch u.kind {
	case "":
		return loom.InvalidEnumValueError("type", "", []any{
			string(InitiativeRequestKindInitiativeList),
			string(InitiativeRequestKindInitiativeRetrieve),
			string(InitiativeRequestKindInitiativeCreate),
			string(InitiativeRequestKindInitiativeUpdate),
			string(InitiativeRequestKindInitiativeDelete),
			string(InitiativeRequestKindInitiativeListProjects),
			string(InitiativeRequestKindInitiativeListWorkitems),
			string(InitiativeRequestKindInitiativeAddProjects),
			string(InitiativeRequestKindInitiativeRemoveProjects),
			string(InitiativeRequestKindInitiativeManageWorkitems),
		})
	case InitiativeRequestKindInitiativeList:
		return nil
	case InitiativeRequestKindInitiativeRetrieve:
		return nil
	case InitiativeRequestKindInitiativeCreate:
		return nil
	case InitiativeRequestKindInitiativeUpdate:
		return nil
	case InitiativeRequestKindInitiativeDelete:
		return nil
	case InitiativeRequestKindInitiativeListProjects:
		return nil
	case InitiativeRequestKindInitiativeListWorkitems:
		return nil
	case InitiativeRequestKindInitiativeAddProjects:
		return nil
	case InitiativeRequestKindInitiativeRemoveProjects:
		return nil
	case InitiativeRequestKindInitiativeManageWorkitems:
		return nil
	default:
		return loom.InvalidEnumValueError("type", u.kind, []any{
			string(InitiativeRequestKindInitiativeList),
			string(InitiativeRequestKindInitiativeRetrieve),
			string(InitiativeRequestKindInitiativeCreate),
			string(InitiativeRequestKindInitiativeUpdate),
			string(InitiativeRequestKindInitiativeDelete),
			string(InitiativeRequestKindInitiativeListProjects),
			string(InitiativeRequestKindInitiativeListWorkitems),
			string(InitiativeRequestKindInitiativeAddProjects),
			string(InitiativeRequestKindInitiativeRemoveProjects),
			string(InitiativeRequestKindInitiativeManageWorkitems),
		})
	}
}

